#!/usr/bin/env python
"""launch.py -- generated by /mhs-setup

Loads setup.yaml via MhsDriver.from_yaml() and runs the setup through
mhs.mhs_api.Publisher (storage dict + mount + 60 Hz sensor/control poll
+ watchdog). The driver class is synthesized from the YAML declarations
-- no separate slot_map.py is needed.

If a sibling rig_target.py exists (frozen filename contract), its
build_target() provides the object that the YAML getter/setter
attribute paths resolve against (the hardware driver object, or a
simulator). Without it, every slot is a stub reading None.

Modes
-----
(default)        Blocking multi-process publisher. Other processes
                 attach to the storage segment by setup name (storage
                 defaults to shm in this mode).
--dry-run        Mount and verify the manifest builds, then exit
                 (storage defaults to inmem -- validation never
                 allocates shared-memory segments).
--dry-run --json Same, but print the manifest as JSON on stdout
                 (status lines go to stderr) for machine consumption.
--serve          Single-process mode for simulated setups / CI
                 (storage defaults to inmem): publisher plus an
                 in-process MCP bridge served over SSE on 127.0.0.1.
                 Reads every slot at startup and prints one
                 "VERIFY ..." line per slot.
--estop-drill    With --serve: after the slot verification, fire the
                 emergency stop path (sets __estop__, applies each
                 CONTROL slot's on_disconnect policy), assert the
                 observable effects, then restart the publisher (the
                 latch clears only by restart) and continue serving.
--port PORT      SSE port for --serve (default 8765).
--storage S      Override the per-mode storage default (shm | inmem).

Storage is selected per object, in code -- the value above is passed
as Publisher(storage=...). The retired MHS_STORAGE / MHS_TRANSPORT
environment variables are never read.
"""
from __future__ import annotations

import argparse
import json
import math
import sys
import threading
import time
from pathlib import Path

SETUP_DIR = Path(__file__).resolve().parent
SETUP_CONFIG = SETUP_DIR / "setup.yaml"


def _fail(msg: str, code: int = 2) -> "NoReturn":  # noqa: F821
    print("[mhs] ERROR: " + msg, file=sys.stderr)
    raise SystemExit(code)


def load_cfg() -> dict:
    import yaml
    if not SETUP_CONFIG.exists():
        _fail("setup.yaml not found next to launch.py")
    with open(SETUP_CONFIG, encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def build_target():
    """Import sibling rig_target.py and call build_target(), if present.

    rig_target.py is where /mhs-setup puts driver/simulator construction
    code. Its build_target() must return the object whose attribute
    paths the setup.yaml getters/setters resolve against, with all
    devices already connected and READY.
    """
    if not (SETUP_DIR / "rig_target.py").exists():
        return None
    sys.path.insert(0, str(SETUP_DIR))
    try:
        import rig_target  # noqa: PLC0415
    finally:
        sys.path.pop(0)
    if not hasattr(rig_target, "build_target"):
        _fail("rig_target.py exists but has no build_target() function")
    return rig_target.build_target()


def make_publisher(cfg: dict, target, storage: str):
    from mhs.mhs_api.driver import MhsDriver
    from mhs.mhs_api.publisher import Publisher

    # The setup.yaml top-level "rig:" section name is a frozen
    # compatibility contract (existing user files carry it).
    meta = cfg.get("rig") or {}
    name = meta.get("name") or cfg.get("device_id") or "setup"
    driver = MhsDriver.from_yaml(str(SETUP_CONFIG), target=target)
    # shm_name == setup name is the attach contract: clients use
    # MhsDict("<setup_name>", mode="attach"). On inmem the name is
    # process-local.
    # Publisher is DEPRECATED in this SDK (issue #256: compose
    # MhsDict.attach() + driver mount/start) but remains the paved
    # composition here; its DeprecationWarning in logs is expected.
    return Publisher(
        driver=driver,
        setup_name=name,
        shm_name=name,
        setup_description=meta.get("description", ""),
        storage=storage,
    )


# ---------------------------------------------------------------------------
# Verification helpers (--serve / --estop-drill)
# ---------------------------------------------------------------------------

def _value(v):
    """Normalize a read result to its plain payload value.

    MhsDict reads already return plain Python values on this SDK
    (the scalar unwrap in MhsDict.__getitem__); this helper is
    belt-and-braces for raw FormatDict reads and older trees where a
    chain tuple or a Format instance (value on .data) can surface --
    there, the payload is the LAST element.
    """
    if isinstance(v, tuple) and v:
        v = v[-1]
    return v.data if hasattr(v, "data") else v


def verify_all_slots(d) -> int:
    """Read every manifest slot; print one VERIFY line each.

    Returns the number of failures. A stub slot reading None/0.0 still
    counts as OK here -- this proves the format chain decodes, not that
    hardware exists.
    """
    failures = 0
    for entry in (d.manifest.get("state") or []):
        key = entry["key"]
        try:
            v = _value(d[key])
            print("VERIFY OK %s = %r" % (key, v), flush=True)
        except Exception as e:  # noqa: BLE001 -- report, never crash verify
            failures += 1
            print("VERIFY FAIL %s : %s: %s" % (key, type(e).__name__, e),
                  flush=True)
    print("VERIFY DONE failures=%d" % failures, flush=True)
    return failures


def _expected_after_estop(entry: dict):
    """Return the value a CONTROL slot must read after estop, or None
    if the policy leaves it unchecked (HOLD / unset / NaN safe_min).

    Bounds ride the payload chain entry on current manifests (the
    slot-level range/safe fields are a deprecated fallback);
    entry_bounds merges both shapes."""
    from mhs.mhs_api.manifest import entry_bounds
    policy = entry.get("on_disconnect")
    if policy == "ZERO":
        return 0.0
    if policy == "SAFE":
        safe = entry_bounds(entry).get("safe") or []
        if safe and safe[0] is not None:
            v = float(safe[0])
            return None if math.isnan(v) else v
    return None


def _matches_target(got, want: float) -> bool:
    """Scalar slots compare directly; array slots compare elementwise
    (the policy broadcasts one safe value across the array)."""
    if isinstance(got, (int, float)):
        return float(got) == want
    try:
        import numpy as np  # noqa: PLC0415 -- optional on minimal installs
        if isinstance(got, np.ndarray):
            return bool((np.asarray(got, dtype=float) == want).all())
    except ImportError:
        pass
    return False


def run_estop_drill(d) -> int:
    """Fire the estop path and assert the observable effects.

    Returns the number of failed assertions. Safe values stay applied
    after the drill (that IS the post-estop state), and the __estop__
    flag stays LATCHED: the latch is one-way -- nothing in the SDK
    clears it, and this template does not reach below the value
    surface to force it. Recovery is the documented one: restart the
    publisher (run_serve does exactly that after a clean drill).
    """
    from mhs.mhs_api.constants import ESTOP_KEY
    from mhs.mhs_api.manifest import trigger_estop

    manifest = d.manifest
    n_checkable = sum(1 for e in (manifest.get("state") or [])
                      if _expected_after_estop(e) is not None)
    if n_checkable == 0:
        # A drill with nothing to verify proves nothing -- usually the
        # user slots failed to mount. Fail loudly instead of passing
        # vacuously.
        print("ESTOP DRILL FAIL no CONTROL slots with ZERO/SAFE policies "
              "to verify -- are the user slots mounted?", flush=True)
        return 1

    try:
        n_applied = trigger_estop(d)
    except Exception as e:  # noqa: BLE001 -- a failed drill is a result
        print("ESTOP DRILL FAIL trigger raised %s: %s -- a policy this "
              "SDK build cannot apply must be escalated to the operator, "
              "not worked around" % (type(e).__name__, e), flush=True)
        return 1
    print("ESTOP DRILL engaged: on_disconnect applied to %d slot(s)"
          % n_applied, flush=True)

    failures = 0
    flag = _value(d[ESTOP_KEY])
    if not bool(flag):
        failures += 1
        print("ESTOP DRILL FAIL %s = %r, expected True after trigger"
              % (ESTOP_KEY, flag), flush=True)
    else:
        print("ESTOP DRILL OK %s = True" % ESTOP_KEY, flush=True)

    for entry in (manifest.get("state") or []):
        want = _expected_after_estop(entry)
        if want is None:
            continue
        key = entry["key"]
        try:
            got = _value(d[key])
            if _matches_target(got, want):
                print("ESTOP DRILL OK %s = %r (policy %s)"
                      % (key, got, entry.get("on_disconnect")), flush=True)
            else:
                failures += 1
                print("ESTOP DRILL FAIL %s = %r, expected %r (policy %s)"
                      % (key, got, want, entry.get("on_disconnect")),
                      flush=True)
        except Exception as e:  # noqa: BLE001
            failures += 1
            print("ESTOP DRILL FAIL %s read error: %s: %s"
                  % (key, type(e).__name__, e), flush=True)

    # No flag reset here: plain assignment to __estop__ is refused by
    # design, and the SDK has no sanctioned owner-side clear surface
    # (python-sdk#463 tracks the future owner-side clear primitive).
    # Recovery is restart-to-clear -- run_serve restarts the publisher.
    print("ESTOP DRILL done: %s stays latched (restart clears it), "
          "drill failures=%d" % (ESTOP_KEY, failures), flush=True)
    return failures


# ---------------------------------------------------------------------------
# Modes
# ---------------------------------------------------------------------------

def run_dry(cfg: dict, as_json: bool, storage: str) -> int:
    import contextlib
    status = sys.stderr if as_json else sys.stdout
    if as_json:
        # The manifest must be the ONLY stdout: rig_target.py and driver
        # construction are allowed to print (and generated targets often
        # do) -- shunt everything they emit to stderr.
        with contextlib.redirect_stdout(sys.stderr):
            pub = make_publisher(cfg, build_target(), storage)
            pub.start()
    else:
        pub = make_publisher(cfg, build_target(), storage)
        pub.start()
    try:
        print("[mhs] setup mounted from setup.yaml", file=status)
        if as_json:
            print(json.dumps(pub.dict.manifest))
        print("Dry-run OK", file=status)
    finally:
        pub.stop()
    return 0


def run_serve(cfg: dict, port: int, estop_drill: bool, storage: str) -> int:
    """Single-process mode: publisher + slot verify [+ estop drill]
    + in-process MCP bridge over SSE. Blocks until SIGINT/SIGTERM."""
    target = build_target()
    pub = make_publisher(cfg, target, storage)
    pub.start()
    try:
        d = pub.dict
        failures = verify_all_slots(d)
        if estop_drill:
            failures += run_estop_drill(d)
        if failures:
            _fail("%d verification failure(s); not serving a broken setup"
                  % failures, code=1)

        if estop_drill:
            # Restart-to-clear: the drill left __estop__ latched (the
            # latch is one-way). A clean stop discards the drilled
            # dict, flag included; the fresh publisher starts clear --
            # the same recovery watch_estop names for a live estop.
            print("ESTOP DRILL recovery: restarting the publisher to "
                  "clear the latch", flush=True)
            pub.stop()
            pub = make_publisher(cfg, target, storage)
            pub.start()
            d = pub.dict
            # Re-verify the RESTARTED publisher -- it, not the drilled
            # one, is what serves; the evidence must attach to it.
            if verify_all_slots(d):
                _fail("restarted publisher failed slot verification; "
                      "not serving a broken setup", code=1)

        # Runtime estop: the drill above proves the path at startup;
        # the watcher honors a stop fired later through the bridge.
        threading.Thread(target=watch_estop, args=(pub,), daemon=True,
                         name="estop-watch").start()

        import anyio
        import uvicorn
        from mcp.server.sse import SseServerTransport
        from starlette.applications import Starlette
        from starlette.responses import Response
        from starlette.routing import Mount, Route

        from mhs_mcp.direct import MhsBridge

        bridge = MhsBridge(d)
        server = bridge.make_server()
        sse = SseServerTransport("/messages/")

        async def handle_sse(request):
            async with sse.connect_sse(
                request.scope, request.receive, request._send,
            ) as streams:
                async with anyio.create_task_group() as tg:
                    tg.start_soon(bridge.run_poller)
                    await server.run(
                        streams[0], streams[1],
                        server.create_initialization_options())
            return Response()

        app = Starlette(routes=[
            Route("/sse", endpoint=handle_sse, methods=["GET"]),
            Mount("/messages/", app=sse.handle_post_message),
        ])
        print("SERVING setup=%s mcp=http://127.0.0.1:%d/sse storage=%s"
              % ((cfg.get("rig") or {}).get("name", "setup"), port, storage),
              flush=True)
        # 127.0.0.1 only -- never expose the bridge beyond this machine.
        uvicorn.run(app, host="127.0.0.1", port=port, log_level="warning")
        return 0
    finally:
        pub.stop()


def watch_estop(pub) -> None:
    """Honor a runtime emergency stop fired from outside this process.

    The bridge's estop tool (and any fleet caller) sets `__estop__`
    and NOTHING else -- applying each CONTROL slot's `on_disconnect`
    policy is this owner process's job. On the flag's rising edge,
    run `trigger_estop` (the same body the watchdog runs on heartbeat
    loss) so policy values land in the slots and the control poll
    pushes them to the hardware setters. The flag stays SET until
    the publisher is restarted -- clearing it is deliberate, never
    remote (the startup drill recovers the same way).

    The 0.1 s sleep-poll below is deliberate: the buffer layer's raw
    wait catalog has no typed owner-side surface on this SDK, and a
    typed wait-for-change is pending upstream (python-sdk#471) --
    swap the loop for it when it lands.
    """
    from mhs.mhs_api.constants import ESTOP_KEY
    from mhs.mhs_api.manifest import trigger_estop

    while getattr(pub, "dict", None) is None:
        time.sleep(0.2)
    d = pub.dict
    fired = False
    while True:
        try:
            engaged = bool(_value(d[ESTOP_KEY]))
        except Exception:  # noqa: BLE001 -- dict closing at shutdown
            return
        if engaged and not fired:
            n = trigger_estop(d)
            print("[mhs] ESTOP ENGAGED -- %d slot(s) set to their "
                  "on_disconnect policy; restart the publisher to "
                  "clear the flag" % n, flush=True)
            fired = True
        time.sleep(0.1)


def run_publisher(cfg: dict, storage: str) -> int:
    """Default: blocking multi-process publisher (systemd-style)."""
    pub = make_publisher(cfg, build_target(), storage)
    print("[mhs] setup mounted from setup.yaml", flush=True)
    threading.Thread(target=watch_estop, args=(pub,), daemon=True,
                     name="estop-watch").start()
    pub.run()
    return 0


def main() -> int:
    p = argparse.ArgumentParser(
        description="Launch MHS setup from setup.yaml")
    p.add_argument("--dry-run", action="store_true",
                   help="mount and verify, then exit")
    p.add_argument("--json", action="store_true",
                   help="with --dry-run: print manifest JSON to stdout")
    p.add_argument("--serve", action="store_true",
                   help="single-process mode: publisher + in-process MCP "
                        "bridge over SSE (simulated setups / inmem)")
    p.add_argument("--estop-drill", action="store_true",
                   help="with --serve: fire and verify the estop path "
                        "before serving")
    p.add_argument("--port", type=int, default=8765,
                   help="SSE port for --serve (default 8765)")
    p.add_argument("--storage", choices=("shm", "inmem"), default=None,
                   help="storage backend; defaults per mode (publisher: "
                        "shm; --serve / --dry-run: inmem)")
    args = p.parse_args()

    # Per-mode storage defaults; --storage overrides. Selected in code
    # and passed as Publisher(storage=...) -- no environment variable.
    if args.storage is not None:
        storage = args.storage
    elif args.serve or args.dry_run:
        storage = "inmem"
    else:
        storage = "shm"

    cfg = load_cfg()

    try:
        if args.dry_run:
            return run_dry(cfg, args.json, storage)
        if args.serve:
            return run_serve(cfg, args.port, args.estop_drill, storage)
        return run_publisher(cfg, storage)
    except KeyboardInterrupt:
        return 0


if __name__ == "__main__":
    raise SystemExit(main())
